PENAL_HERITAGE_ARTICLES = tuple(str(n).translate(F) for n in range(558, 570))


def one(conn, query, value):
    row = conn.execute(query, (value,)).fetchone()
    return row["id"] if row else None


def parse(f, n):
    lines = (ROOT / "data/source_cache" / f).read_text().splitlines()
    heads = []
    for i, line in enumerate(lines):
        match = re.match(r"^\s*ماده\s*([۰-۹0-9]+)", line.replace("*", "").replace("#", "").replace("\u200c", " "))
        if match:
            heads.append((int(match.group(1).translate(D)), i))
    out = []
    for article_no in range(1, n + 1):
        pos = next(idx for idx, (num, _) in enumerate(heads) if num == article_no)
        begin = heads[pos][1]
        end = heads[pos + 1][1] if pos + 1 < len(heads) else len(lines)
        text = "\n".join(lines[begin:end])
        text = re.sub(r"\[([^]]+)\]\([^)]+\)", r"\1", text).replace("**", "").replace("ي", "ی").replace("ك", "ک")
        text = re.sub(r"^ماده\s*[۰-۹0-9]+\s*[-ـ–:]?\s*", "", text.strip(), 1)
        out.append((str(article_no).translate(F), re.sub(r"[ \t]+", " ", text).strip()))
    return out


def upsert_doc(conn, ref, title, short, date, notes, type_code="law", authority="مجلس شورای اسلامی", status_code="in_force"):
    did = one(conn, "SELECT id FROM documents WHERE reference_code=?", ref)
    if not did:
        did = get_or_create_document(
            conn,
            title=title,
            short_title=short,
            type_code=type_code,
            issuing_authority=authority,
            status_code=status_code,
            ratification_date=date,
            effective_date=date,
            reference_code=ref,
            notes=notes,
        )
    conn.execute(
        """
        UPDATE documents
        SET title=?, short_title=?, type_id=?, issuing_authority_id=?, status_id=?, notes=?, ratification_date=?, effective_date=?
        WHERE id=?
        """,
        (
            title,
            short,
            one(conn, "SELECT id FROM document_types WHERE code=?", type_code),
            one(conn, "SELECT id FROM authorities WHERE name_fa=?", authority),
            one(conn, "SELECT id FROM statuses WHERE code=?", status_code),
            notes,
            date,
            date,
            did,
        ),
    )
    return did


def clear_owned(conn, did):
    for query in (
        "DELETE FROM relations WHERE from_document_id=?",
        "DELETE FROM articles_fts WHERE document_id=?",
        "DELETE FROM articles WHERE document_id=?",
        "DELETE FROM document_tags WHERE document_id=?",
        "DELETE FROM document_topics WHERE document_id=?",
    ):
        conn.execute(query, (did,))


def attach(conn, did, extra_tags=()):
    for topic in ("حقوق عمومی", "گردشگری، میراث فرهنگی و آثار تاریخی"):
        conn.execute("INSERT OR IGNORE INTO topics(name_fa) VALUES(?)", (topic,))
        link_document_topic(conn, did, topic)
    for tag in sorted(set(("گردشگری", "میراث فرهنگی", "آثار تاریخی", "صنایع دستی")) | set(extra_tags)):
        link_document_tag(conn, did, add_tag(conn, tag))


def add_rows(conn, did, ref, date, rows, source):
    for raw_no, text in rows:
        article_no = str(raw_no).translate(F)
        key_no = str(raw_no).translate(D).replace(" ", "-")
        add_article(
            conn,
            did,
            article_no=article_no,
            article_key=f"{ref}:{key_no}",
            version_no=1,
            is_current=1,
            effective_date=date,
            text=text,
            source_note=source,
        )


def add_rel(conn, from_ref, to_ref, rel_type="cites", desc=None):
    from_doc = one(conn, "SELECT id FROM documents WHERE reference_code=?", from_ref)
    to_doc = one(conn, "SELECT id FROM documents WHERE reference_code=?", to_ref)
    if from_doc and to_doc:
        add_relation(conn, from_doc, rel_type, to_doc, description=desc or f"پیوند موضوعی {from_ref} با {to_ref}.")


def load_penal_heritage_extract(conn):
    ref = "QMA-HERITAGE-1392"
    date = "1996-05-22"
    did = upsert_doc(
        conn,
        ref,
        "بخش جرایم علیه میراث فرهنگی در کتاب پنجم قانون مجازات اسلامی",
        "جرایم علیه میراث فرهنگی و آثار تاریخی",
        date,
        "گزیده لفظی مواد ۵۵۸ تا ۵۶۹ کتاب پنجم قانون مجازات اسلامی درباره میراث فرهنگی؛ متن از سند قانون مجازات اسلامی موجود در بانک بازنشر شده است.",
    )
    clear_owned(conn, did)
    attach(conn, did, ("جرایم علیه میراث فرهنگی", "حفاری غیرمجاز", "اشیاء عتیقه"))
    qma = conn.execute("SELECT id FROM documents WHERE reference_code='QMA-1392'").fetchone()
    if not qma:
        return
    rows = conn.execute(
        """
        SELECT article_no, text, source_note
        FROM articles
        WHERE document_id=? AND article_no IN ({}) AND is_current=1
        ORDER BY CAST(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(article_no,'۰','0'),'۱','1'),'۲','2'),'۳','3'),'۴','4'),'۵','5'),'۶','6'),'۷','7'),'۸','8'),'۹','9') AS INTEGER)
        """.format(",".join("?" for _ in PENAL_HERITAGE_ARTICLES)),
        (qma["id"], *PENAL_HERITAGE_ARTICLES),
    ).fetchall()
    for row in rows:
        add_article(
            conn,
            did,
            article_no=row["article_no"],
            article_key=f"{ref}:{row['article_no'].translate(D)}",
            version_no=1,
            is_current=1,
            effective_date=date,
            text=row["text"],
            source_note=row["source_note"] or SOURCE_URLS[ref],
            notes="بازنشر ماده از سند قانون مجازات اسلامی برای بسته موضوعی میراث فرهنگی.",
        )
    add_rel(conn, ref, "QMA-1392", "cites", "این سند گزیده مواد ۵۵۸ تا ۵۶۹ قانون مجازات اسلامی در حوزه میراث فرهنگی است.")


